          <h2 class="overlay-title">{{ isLogin ? '创建账号' : '登入账号' }}</h2>
          <p class="overlay-subtitle">{{ isLogin ? '什么？你还没有账号？快去注册吧' : '已经有账号了，登入账号' }}</p>
          <button 
            class="overlay-btn"
            @click="toggleAuthMode"
            :disabled="isLoading"
          >
