<script>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'

const API_BASE_URL = 'https://api.banana404.top'

export default {
  name: 'AuthPage',
  setup() {
    const router = useRouter()
    let countdownTimer = null
    const isLogin = ref(true)
    const isLoading = ref(false)
    const showLoginPassword = ref(false)
    const showRegisterPassword = ref(false)
    const showConfirmPassword = ref(false)
    const loginError = ref('')
    const registerError = ref('')
    const registerSuccess = ref('')
    const codeSalt = ref('')
    const isCodeSent = ref(false)
    const isCountingDown = ref(false)
    const countdown = ref(60)

    const loginForm = ref({
      usernameEmail: '',
      password: ''
    })

    const registerForm = ref({
      username: '',
      email: '',
      password: '',
      confirmPassword: '',
      code: ''
    })

    onMounted(() => {
      const shapes = document.querySelectorAll('.shape')
      
      shapes.forEach((shape, index) => {
        setTimeout(() => {
          shape.classList.add('animate')
        }, 300 + index * 150)
      })
    })

    onUnmounted(() => {
      if (countdownTimer) {
        clearInterval(countdownTimer)
        countdownTimer = null
      }
    })

    const passwordMismatch = computed(() => {
      return registerForm.value.password && 
             registerForm.value.confirmPassword && 
             registerForm.value.password !== registerForm.value.confirmPassword
    })

    const isFormValid = computed(() => {
      return registerForm.value.username &&
             registerForm.value.email &&
             registerForm.value.password &&
             registerForm.value.confirmPassword &&
             registerForm.value.code &&
             codeSalt.value &&
             !passwordMismatch.value
    })

    const toggleAuthMode = () => {
      if (isLoading.value) return
      isLogin.value = !isLogin.value
      loginError.value = ''
      registerError.value = ''
      registerSuccess.value = ''
      
      if (countdownTimer) {
        clearInterval(countdownTimer)
        countdownTimer = null
      }
      isCountingDown.value = false
      countdown.value = 60
      isCodeSent.value = false
      codeSalt.value = ''
    }
    
    // 返回上一页功能
    const goBack = () => {
      router.back()
    }

    const startCountdown = () => {
      isCountingDown.value = true
      countdown.value = 60
      
      if (countdownTimer) {
        clearInterval(countdownTimer)
      }
      
      countdownTimer = setInterval(() => {
        countdown.value--
        if (countdown.value <= 0) {
          clearInterval(countdownTimer)
          countdownTimer = null
          isCountingDown.value = false
        }
      }, 1000)
    }

    const handleSendCode = async () => {
      if (!registerForm.value.email) {
        registerError.value = '请输入邮箱地址'
        return
      }

      isLoading.value = true
      registerError.value = ''

      try {
        const response = await fetch(`${API_BASE_URL}/api/v1/user/email/code/register`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          credentials: 'include',
          body: JSON.stringify({
            email: registerForm.value.email
          })
        })

        const data = await response.json()

        if (data.code === 200) {
          codeSalt.value = data.data?.codeSalt || ''
          isCodeSent.value = true
          registerSuccess.value = '验证码已发送，请查收邮箱'
          startCountdown()
        } else {
          registerError.value = data.msg || '发送验证码失败'
        }
      } catch (error) {
        console.error('发送验证码错误:', error)
        registerError.value = '网络错误，请稍后重试'
      } finally {
        isLoading.value = false
      }
    }

    const handleLogin = async () => {
      if (!loginForm.value.usernameEmail || !loginForm.value.password || isLoading.value) return
      
      isLoading.value = true
      loginError.value = ''
      
      try {
        const response = await fetch(`${API_BASE_URL}/api/v1/user/login`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          credentials: 'include',
          body: JSON.stringify({
            email: loginForm.value.usernameEmail,
            passwd: loginForm.value.password
          })
        })

        const data = await response.json()

        if (data.code === 200) {
          localStorage.setItem('realUserInfo', JSON.stringify(data.data))
          
          // 设置跨子域 Cookie
          const domain = '.hkmre.top'; // 主域名，前面加 dot 表示所有子域名都能访问
          const expires = new Date();
          expires.setTime(expires.getTime() + (7 * 24 * 60 * 60 * 1000)); // 7天过期
          
          // 从响应中获取认证信息，根据后端实际返回结构调整
          // 注意：实际项目中，认证信息可能在 cookie 中由后端设置
          // 这里我们手动设置一个跨域 cookie 用于子域名访问
          const userData = data.data || {};
          
          // 使用与后端一致的 cookie 名称
          document.cookie = `forestwhisper=${JSON.stringify(userData)}; path=/; domain=${domain}; expires=${expires.toUTCString()}; secure; sameSite=none`;
          
          router.push('/user-panel')
        } else {
          loginError.value = data.msg || '登录失败，请检查邮箱和密码'
        }
      } catch (error) {
        console.error('登录错误:', error)
        loginError.value = '网络错误，请检查网络连接'
      } finally {
        isLoading.value = false
      }
    }

    const handleRegister = async () => {
      if (!isFormValid.value || isLoading.value) return
      
      isLoading.value = true
      registerError.value = ''
      registerSuccess.value = ''
      
      try {
        const response = await fetch(`${API_BASE_URL}/api/v1/user/register`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          credentials: 'include',
          body: JSON.stringify({
            email: registerForm.value.email,
            username: registerForm.value.username,
            passwd: registerForm.value.password,
            code: registerForm.value.code
          })
        })

        const data = await response.json()

        if (data.code === 200) {
          registerSuccess.value = '注册成功！正在跳转到登录...'
          setTimeout(() => {
            isLogin.value = true
            loginForm.value.usernameEmail = registerForm.value.email
            registerForm.value = {
              username: '',
              email: '',
              password: '',
              confirmPassword: '',
              code: ''
            }
            codeSalt.value = ''
            isCodeSent.value = false
            registerSuccess.value = ''
          }, 2000)
        } else {
          registerError.value = data.msg || '注册失败，请检查输入信息'
        }
      } catch (error) {
        console.error('注册错误:', error)
        registerError.value = '网络错误，请稍后重试'
      } finally {
        isLoading.value = false
      }
    }

    return {
      isLogin,
      isLoading,
      showLoginPassword,
      showRegisterPassword,
      showConfirmPassword,
      loginForm,
      registerForm,
      passwordMismatch,
      isFormValid,
      loginError,
      registerError,
      registerSuccess,
      codeSalt,
      isCodeSent,
      isCountingDown,
      countdown,
      toggleAuthMode,
      handleLogin,
      handleRegister,
      handleSendCode,
      goBack
    }
  }
}
</script>

